/**
 * generated by stackra gen from src/config/seo.config.ts (sitemapPageSize), gen/sitemap.ts,
 * src/routes/site/site.layout.ts and context.ts — do not edit
 * Purpose: `/sitemap.xml`: the index of every sitemap file, one or more per source (marketing,
 *          pages, products): a source longer than one page is split into numbered files, and an
 *          empty source still lists its first file, which answers a valid empty sitemap.
 * Boundary: a non-indexable site has no sitemap; the index answers 404 there. The paging walks each
 *           source's cursor once per edge-cache lifetime and keeps each file within the protocol's
 *           50,000 URLs (`@stackra/seo`).
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/react";
import { SeoConfig, sitemapFiles, writeSitemapIndex } from "@stackra/seo";
import type { Route } from "./+types/sitemap-index";
import { SiteLayout } from "#src/routes/site/site.layout";
import { sitemapSources } from "#stackra/sitemap";
import { routeKeys } from "../context";

/** The index of the site's sitemap files, or 404 for a site that is not indexed. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args, routeKeys);
  const { site } = await ctx.layout(SiteLayout);
  if (!site.indexable) return new Response(null, { status: 404 });
  const files = await sitemapFiles(sitemapSources, {
    clients: ctx.clients,
    site,
    href: ctx.href,
    pageSize: ctx.config(SeoConfig).sitemapPageSize,
  });
  const body = writeSitemapIndex(
    files.map(({ source, page }) => `${site.origin}/sitemaps/${source}-${page}.xml`),
  );
  return new Response(body, {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
